import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import api from '../lib/axios.js';

export const walletKeys = {
  balance: ['wallet', 'balance'],
  recipients: (q) => ['wallet', 'recipients', q],
};

/**
 * Wallet hook: balance query + peer-to-peer transfer mutation. The transfer
 * sends an Idempotency-Key header (generated by the caller) and, on success,
 * invalidates the balance and transaction queries so the UI auto-refreshes.
 */
export function useWallet() {
  const qc = useQueryClient();

  const balanceQuery = useQuery({
    queryKey: walletKeys.balance,
    queryFn: async () => {
      const { data } = await api.get('/api/wallet/balance');
      return data.data; // { balance, currency }
    },
  });

  const transferMutation = useMutation({
    mutationFn: async ({ recipientEmail, amount, description, idempotencyKey }) => {
      const { data } = await api.post(
        '/api/wallet/transfer',
        { recipientEmail, amount, description },
        { headers: { 'Idempotency-Key': idempotencyKey } }
      );
      return data.data;
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: walletKeys.balance });
      qc.invalidateQueries({ queryKey: ['transactions'] });
    },
  });

  return {
    balance: balanceQuery.data?.balance ?? 0,
    currency: balanceQuery.data?.currency ?? 'KES',
    balanceQuery,
    transfer: transferMutation.mutateAsync,
    transferMutation,
  };
}

/**
 * Debounced recipient search by name/email.
 * @param {string} query
 */
export function useRecipientSearch(query) {
  return useQuery({
    queryKey: walletKeys.recipients(query),
    enabled: query.trim().length >= 2,
    staleTime: 10_000,
    queryFn: async () => {
      const { data } = await api.get('/api/wallet/recipients', {
        params: { q: query.trim() },
      });
      return data.data.recipients; // [{ id, name, email }]
    },
  });
}

export default useWallet;

/**
 * Paying several people in one entry, and giving money back.
 *
 * Both live here rather than in their own hook because they are the same
 * wallet: a split is a transfer with more than one payee, and a refund is a
 * transfer pointed back at whoever paid.
 */
export function useWalletExtras() {
  const qc = useQueryClient();
  const refresh = () => {
    qc.invalidateQueries({ queryKey: walletKeys.balance });
    qc.invalidateQueries({ queryKey: ['transactions'] });
    qc.invalidateQueries({ queryKey: ['savings', 'goals'] });
  };

  const splitMutation = useMutation({
    mutationFn: async ({ recipients, amount, shares, description, idempotencyKey }) => {
      const { data } = await api.post(
        '/api/wallet/split',
        { recipients, amount, shares, description },
        { headers: { 'Idempotency-Key': idempotencyKey } }
      );
      return data.data;
    },
    onSuccess: refresh,
  });

  const refundMutation = useMutation({
    mutationFn: async ({ entryId, amount, reason, idempotencyKey }) => {
      const { data } = await api.post(
        '/api/wallet/refund',
        { entryId, amount, reason },
        { headers: { 'Idempotency-Key': idempotencyKey } }
      );
      return data.data;
    },
    onSuccess: refresh,
  });

  return { split: splitMutation.mutateAsync, splitMutation, refund: refundMutation.mutateAsync, refundMutation };
}

/**
 * How much of a received payment can still be given back. Asked before the
 * refund button is offered, so a payment that is already fully refunded shows
 * as such instead of failing on submit.
 *
 * @param {string|null} entryId
 * @param {boolean} enabled
 */
export function useRefundable(entryId, enabled = true) {
  return useQuery({
    queryKey: ['wallet', 'refundable', entryId],
    enabled: Boolean(entryId) && enabled,
    retry: false,
    queryFn: async () => {
      const { data } = await api.get(`/api/wallet/transactions/${entryId}/refundable`);
      return data.data;
    },
  });
}
